mapper.select:
select t.task_id_ as taskId,t.act_id_ as taskDefKey,t.act_name_ as taskName,t.MESSAGE_ as message,t.TYPE_ as messageType,t.TIME_ as messageTime
,t.USER_ID_ as messageUserId,t.ASSIGNEE_ as assigneeId ,t.START_TIME_ as createTime,t.END_TIME_ as finishTime
from (
    
    select actinst.task_id_,actinst.act_id_,actinst.act_name_,comment.MESSAGE_,comment.TYPE_,comment.USER_ID_ ,actinst.ASSIGNEE_ ,actinst.START_TIME_ ,actinst.END_TIME_,actinst.act_type_,comment.TIME_
    from act_hi_actinst actinst
    left join ACT_HI_COMMENT comment on comment.TASK_ID_ = actinst.TASK_ID_  and comment.ACTION_ ='AddComment'
    where actinst.PROC_INST_ID_ = #{procInsId} and (actinst.END_TIME_ is not null or comment.ID_ is not null)
    union all
    
    select actinst.task_id_,actinst.act_id_,actinst.act_name_,'','',actinst.ASSIGNEE_,actinst.ASSIGNEE_ ,actinst.START_TIME_ ,actinst.END_TIME_,actinst.act_type_,#{defaultDate}
    from act_hi_actinst actinst
    where actinst.END_TIME_ is null and actinst.PROC_INST_ID_ = #{procInsId}
) t
where t.act_type_ in

    #{type}

order by t.START_TIME_ ,t.END_TIME_ ,t.TIME_
